questions.solution:
function isFetchableUrl(text) {
  let url;
  try {
    url = new URL(text);
  } catch {
    return false;
  }
  if (url.protocol !== "http:" && url.protocol !== "https:") return false;
  return url.username === "" && url.password === "";
}

for (const text of ["https://example.com/a", "file:///etc/passwd", "http://user:pass@example.com/", "not a url", "http://example.com:8080/"]) {
  console.log(isFetchableUrl(text), text);
}

