function createLimiter(max) {
  const counts = new Map();
  return (ip) => {
    const count = (counts.get(ip) ?? 0) + 1;
    counts.set(ip, count);
    return count <= max;
  };
}

const check = createLimiter(2);
console.log(check("203.0.113.7"), check("203.0.113.7"), check("203.0.113.7"), check("198.51.100.1"));

