function escapeHtml(text) {
  return text
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;");
}

console.log(escapeHtml('<img src=x onerror="alert(1)">'));
console.log(escapeHtml("Tom & Jerry"));

