function readBodyLimit(text) {
  const limit = Number(text);
  if (!Number.isFinite(limit) || limit <= 0) throw new Error("BODY_LIMIT must be a positive number");
  return limit;
}

for (const text of ["16384", undefined, "abc", "0"]) {
